using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineEditorOperations
{
    public double video_duration(Control owner){double value=owner.Get("_video_duration_override").AsDouble();if(value>0)return value;double end=0;foreach(var clip in Clips(owner)){var resource=clip.As<Resource>();end=Math.Max(end,resource.Get("start_time").AsDouble()+resource.Get("duration").AsDouble());}return end>0?end:10;}
    public void set_video_duration(Control owner,double value){double next=Math.Max(.01,value),previous=owner.Get("_video_duration_override").AsDouble();if(Mathf.IsEqualApprox(previous,next))return;DurationAction(owner,previous,next,"Set Video Duration");}
    private static void DurationAction(Control owner,double before,double after,string title){var history=Model(owner).Get("history").As<UndoRedo>();var action=new TimelineEditorDurationAction(owner,before,after);history.CreateAction(title);history.AddDoMethod(new Callable(action,nameof(TimelineEditorDurationAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(TimelineEditorDurationAction.restore_before)));history.AddDoReference(action);history.CommitAction();}
    public void reset_video_duration(Control owner){double before=owner.Get("_video_duration_override").AsDouble();if(before>0)DurationAction(owner,before,-1,"Reset Video Duration");}
    public void pause_recording_scene(Control owner,bool paused){var viewport=owner.Get("_recording_viewport").As<SubViewport>();if(paused){if(GodotObject.IsInstanceValid(viewport))return;var holder=owner.Get("runtime_holder").As<Node3D>();if(!GodotObject.IsInstanceValid(holder))return;viewport=holder!.GetViewport() as SubViewport;if(viewport==null)return;owner.Set("_recording_viewport",viewport);owner.Set("_saved_viewport_update",(int)viewport.RenderTargetUpdateMode);owner.Set("_saved_scene_process",(int)viewport.ProcessMode);viewport.RenderTargetUpdateMode=SubViewport.UpdateMode.Disabled;viewport.ProcessMode=Node.ProcessModeEnum.Disabled;}else if(GodotObject.IsInstanceValid(viewport)){viewport!.RenderTargetUpdateMode=(SubViewport.UpdateMode)owner.Get("_saved_viewport_update").AsInt32();viewport.ProcessMode=(Node.ProcessModeEnum)owner.Get("_saved_scene_process").AsInt32();owner.Set("_recording_viewport",default(Variant));}}
    public Node? active_recording_audio(Control owner){var screen=owner.Get("screen_recorder").As<Node>();if(screen.Get("recording").AsBool()){var recorder=screen.Get("audio_recorder").As<Node>();if(GodotObject.IsInstanceValid(recorder))return recorder;}var audio=owner.Get("audio_recorder").As<Node>();return audio.Get("recording").AsBool()?audio:null;}
    public bool recording_timeline_audio(Control owner){var recorder=active_recording_audio(owner);return recorder!=null&&recorder.Get("record_timeline").AsBool();}
    public void route_timeline_audio(Control owner){var audio=owner.Get("audio_system").As<Node>();if(audio==null)return;var recorder=active_recording_audio(owner);string destination="Master";if(recorder!=null&&recorder.Get("record_timeline").AsBool()&&recorder.Get("timeline_bus_name").AsString().Length>0)destination=recorder.Get("timeline_bus_name").AsString();_audio.set_output_bus(audio,destination);}
    private static void StopPlayers(Control owner){foreach(var value in owner.Get("audio_system").As<Node>().Get("players").AsGodotDictionary().Values)value.As<AudioStreamPlayer>().Stop();}
    private static void Hint(Control owner,GodotObject source,string text){var hints=owner.Get("hints").AsGodotObject();if(text.Length==0)hints.Call("end",source);else hints.Call("begin",source,text);}
    private static void SetPlaying(Control owner,bool playing){owner.Set("playing",playing);owner.Get("play_button").As<Button>().Text=playing?"Ⅱ":"▶";}
    private static void SetRecordingButton(Control owner,bool screen,bool recording){var button=owner.Get(screen?"screen_button":"mic_button").As<Button>();button.Icon=owner.Call("_toolbar_icon",recording?"stop":screen?"screen":"mic").As<Texture2D>();button.SelfModulate=Colors.White;button.TooltipText=screen?(recording?"Stop screen recording":"Screen recording: choose a display or window and audio sources"):(recording?"Stop recording and create an audio actor (R)":"Record selected audio sources (R); use ▾ for recording options");}
    private void StartPreview(Control owner,bool screen){var canvas=Canvas(owner);owner.Set("_record_start",Time(owner));owner.Set("_record_elapsed",0.0);int layer=Model(owner).Get("selected_layer").AsInt32();foreach(var value in _timeline.section_clips(Model(owner)))layer=Math.Max(layer,value.As<Resource>().Get("layer").AsInt32()+1);owner.Set("_record_layer",layer);canvas.Set("recording_preview",new Settings{["start"]=Time(owner),["duration"]=0.0,["layer"]=layer});if(screen)canvas.Set("recording_peaks",Array.Empty<float>());SetPlaying(owner,true);route_timeline_audio(owner);evaluate_runtimes(owner);SetRecordingButton(owner,screen,true);if(screen)owner.Get("mic_button").As<Button>().Disabled=true;Hint(owner,owner.Get(screen?"screen_recorder":"audio_recorder").AsGodotObject(),screen?"Screen recording • Click screen stop or press Space to finish":"Recording audio • R or the stop button finishes recording");owner.Call("_refresh");if(!screen){var scroll=owner.Get("v_scroll").As<VScrollBar>();scroll.Value=Math.Max(0,(layer+1)*canvas.Get("row_height").AsDouble()-scroll.Page);}}
    public int begin_audio_recording_toggle(Control owner){if(owner.Get("screen_recorder").As<Node>().Get("recording").AsBool()||owner.Get("_record_busy").AsBool())return 0;owner.Set("_record_busy",true);if(owner.Get("audio_recorder").As<Node>().Get("recording").AsBool()){owner.Set("playing",false);evaluate_runtimes(owner);return 2;}owner.Set("playing",false);StopPlayers(owner);pause_recording_scene(owner,true);return 1;}
    public void audio_recording_started(Control owner,string error){owner.Set("_record_busy",false);if(error.Length>0){pause_recording_scene(owner,false);audio_notice(owner,error);return;}StartPreview(owner,false);}
    public void audio_recording_stopped(Control owner,AudioStreamWav? stream){route_timeline_audio(owner);pause_recording_scene(owner,false);owner.Set("_record_busy",false);Canvas(owner).Get("recording_preview").AsGodotDictionary().Clear();SetPlaying(owner,false);evaluate_runtimes(owner);SetRecordingButton(owner,false,false);Hint(owner,owner.Get("audio_recorder").AsGodotObject(),"");if(stream!=null)create_recording(owner,stream);else audio_notice(owner,"No audio was captured. Check the selected recording sources and their permissions.");owner.Call("_refresh");}
    public Resource? create_recording(Control owner,AudioStreamWav stream){var model=Model(owner);model.Set("selected_layer",owner.Get("_record_layer"));var definition=_definitions.get_definition(owner.Get("registry").As<RefCounted>(),"audio");if(definition==null)return null;var clip=_timeline.create_actor(model,definition,owner.Get("_record_start").AsDouble(),new Settings{[new StringName("audio")]=stream});if(clip!=null){var actor=_timeline.actor_for_id(model,clip.Get("actor_id").AsString());actor?.Set("display_name",stream.ResourceName.Length>0?stream.ResourceName:"Audio Recording");model.EmitSignal("changed");}return clip;}
    public void audio_notice(Control owner,string message){var dialog=new AcceptDialog{Title="Audio Recording",DialogText=message};owner.AddChild(dialog);dialog.PopupCentered(new Vector2I(460,130));dialog.Confirmed+=dialog.QueueFree;dialog.Canceled+=dialog.QueueFree;}
    public void toggle_playback(Control owner){if(owner.Get("_record_busy").AsBool())return;if(owner.Get("screen_recorder").As<Node>().Get("recording").AsBool()){owner.Call("_stop_screen_recording");return;}if(owner.Get("audio_recorder").As<Node>().Get("recording").AsBool()){owner.Call("toggle_recording");return;}SetPlaying(owner,!Playing(owner));evaluate_runtimes(owner);}
    public void process(Control owner,double delta){if(Physics(owner).Get("pending").AsBool()&&!owner.Get("exporting").AsBool()&&!Recording(owner)){evaluate_runtimes(owner);if(Physics(owner).Get("pending").AsBool())return;}var canvas=owner.Get("canvas").As<Control>();if(!Playing(owner)||canvas==null)return;canvas.Set("playhead",canvas.Get("playhead").AsDouble()+delta);if(Recording(owner)){double elapsed=owner.Get("_record_elapsed").AsDouble()+delta;owner.Set("_record_elapsed",elapsed);canvas.Get("recording_preview").AsGodotDictionary()["duration"]=elapsed;var screen=owner.Get("screen_recorder").As<Node>();var audio=screen.Get("recording").AsBool()?screen.Get("audio_recorder").As<Node>():null;canvas.Set("recording_peaks",(audio??owner.Get("audio_recorder").As<Node>()).Get("peaks"));}evaluate_runtimes(owner);owner.Call("_refresh");double scroll=canvas.Get("scroll_time").AsDouble(),right=scroll+Math.Max(0,canvas.Size.X-140)/canvas.Get("pixels_per_second").AsDouble();if(Time(owner)>right)owner.Get("h_scroll").As<HScrollBar>().Value=Time(owner)-Math.Max(0,right-scroll)*.8;}
    public bool begin_screen_recording(Control owner){if(owner.Get("_record_busy").AsBool()||Recording(owner))return false;owner.Set("playing",false);StopPlayers(owner);pause_recording_scene(owner,true);owner.Set("_record_busy",true);return true;}
    public void screen_recording_started(Control owner,string error){owner.Set("_record_busy",false);if(error.Length>0){pause_recording_scene(owner,false);audio_notice(owner,error);return;}StartPreview(owner,true);}
    public bool begin_screen_stop(Control owner){if(owner.Get("_record_busy").AsBool()||!owner.Get("screen_recorder").As<Node>().Get("recording").AsBool())return false;owner.Set("_record_busy",true);owner.Set("playing",false);evaluate_runtimes(owner);return true;}
    public void screen_recording_stopped(Control owner,string path){route_timeline_audio(owner);pause_recording_scene(owner,false);owner.Set("_record_busy",false);Canvas(owner).Get("recording_preview").AsGodotDictionary().Clear();owner.Get("play_button").As<Button>().Text="▶";SetRecordingButton(owner,true,false);owner.Get("mic_button").As<Button>().Disabled=false;Hint(owner,owner.Get("screen_recorder").AsGodotObject(),"");owner.Call("_refresh");if(path.Length==0)audio_notice(owner,"Screen recording could not be finalized. "+owner.Get("screen_recorder").As<Node>().Get("last_error").AsString());}
    public void create_screen_recording(Control owner,string path,StringName dimension){if(dimension.ToString().Length==0)return;var model=Model(owner);model.Set("selected_layer",owner.Get("_record_layer"));var definition=_definitions.get_definition(owner.Get("registry").As<RefCounted>(),dimension=="2d"?"video_2d":"video");if(definition==null)return;var clip=_timeline.create_actor(model,definition,owner.Get("_record_start").AsDouble(),new Settings{[new StringName("video")]=path});if(clip!=null){var actor=_timeline.actor_for_id(model,clip.Get("actor_id").AsString());if(actor!=null){actor.Set("display_name","Screen Recording");var audio=_timeline.actor_for_id(model,actor.Get("values").AsGodotDictionary().GetValueOrDefault("linked_audio_actor","").AsString());audio?.Set("display_name","Screen Recording Audio");}model.EmitSignal("changed");}owner.Call("_refresh");}
}
